<?php declare(strict_types=1); use App\Admin\DTO\CompanyAdminFormData; require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session]=admin_empresa_context(); try{$id=filter_var($_POST['empresa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!is_int($id))throw new InvalidArgumentException('Empresa inválida.');$app->companyAdmin()->update($id,CompanyAdminFormData::fromArray($_POST));$session->flash('success','Empresa atualizada com sucesso.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company edit failed: '.get_class($e));$session->flash('danger','Não foi possível atualizar a empresa.');}admin_empresa_redirect($app);
